const j = $input.first().json;
const body = j.body && typeof j.body === 'object' ? j.body : j;
const ts = body.timestamp || new Date().toISOString();
const echo = {
  sensor_id: body.sensor_id,
  valor: body.valor,
  timestamp: ts,
  cultivo: body.cultivo,
  ubicacion: body.ubicacion,
};
return [
  {
    json: {
      payload: {
        action: 'analizar_sensores',
        sensor_id: echo.sensor_id,
        valor: echo.valor,
        timestamp: echo.timestamp,
        cultivo: echo.cultivo,
        ubicacion: echo.ubicacion,
      },
      _echo: echo,
    },
  },
];

const r = $input.first().json;
const b = $('Build_Payload_Sensores').first().json;
const echo = b._echo || {};
if (r.errors && r.errors.length) {
  throw new Error('Castuo LangGraph: ' + r.errors.join('; '));
}
let recs = [];
try {
  const o = JSON.parse(r.analysis);
  if (o && Array.isArray(o.recomendaciones)) recs = o.recomendaciones.map(String);
} catch (e) {
  recs = [];
}
const recomText = recs.length ? recs.join(', ') : String(r.analysis || '').slice(0, 2000);
return [
  {
    json: {
      sensor_id: echo.sensor_id ?? null,
      valor: echo.valor ?? null,
      cultivo: echo.cultivo ?? null,
      ubicacion: echo.ubicacion ?? null,
      timestamp: echo.timestamp ?? new Date().toISOString(),
      analisis: r.analysis ?? '',
      recomendaciones: recs,
      recomendaciones_text: recomText,
      tx_hash: r.trace_hash || '',
      errors: r.errors || [],
      gaia_http_status: r.gaia_http_status,
      slack_http_status: r.slack_http_status,
    },
  },
];
